select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_LOADING_READ','RRL_STOCK_SINGLE_LOAD_CMD','RRL_STOCK_HU_LOAD_CORE','RRL_STOCK_SHIPPING_CORE','RRL_STOCK_POSTING_API') order by OBJECT_NAME,OBJECT_TYPE;
select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME in('RRL_STOCK_LOADING_READ','RRL_STOCK_SINGLE_LOAD_CMD','RRL_STOCK_HU_LOAD_CORE','RRL_STOCK_SHIPPING_CORE','RRL_STOCK_POSTING_API') order by NAME,TYPE,LINE;
